#include <algorithm>

using namespace std;

int main() {
    long long l, r, k;
    cin >> l >> r >> k;

    vector<long long> powers;
    long long power = 1;
    while (power <= r) {
        if (power >= l) {
            powers.push_back(power);
        }
        if (power > r / k) {
            break;
        }
        power *= k;
    }

    if (powers.empty()) {
        cout << -1 << endl;
    } else {
        for (size_t i = 0; i < powers.size(); ++i) {
            cout << powers[i] << (i == powers.size() - 1 ? "" : " ");
        }
        cout << endl;
    }

    return 0;
}

