#include <iostream>
#include <vector>

using namespace std;

bool isBeautiful(long long n) {
    if (n == 0) return true;
    string s = to_string(n);
    int count = 0;
    for (char c : s) {
        if (c == '1') {
            count++;
        } else if (c != '0') {
            return false;
        }
    }
