string reverse_number(int n) {
    string s = to_string(n);
    reverse(s.begin(), s.end());

    // Remove leading zeros
    size_t first_non_zero = s.find_first_not_of('0');
    if (first_non_zero == string::npos) {
        return "0";
    }
    return s.substr(first_non_zero);
