    long long n;
    cin >> n;

    for (long long a = 1; a < n; ++a) {
        string s = to_string(a);
        string ar = flip(s);
        if (ar.empty()) ar = "0";
        long long reversed_a;
        try {
            reversed_a = stoll(ar);
        } catch (const out_of_range& oor) {
            continue;
        }

        if (a + reversed_a == n) {
            cout << a << endl;
            return 0;
        }
    }

    cout << 0 << endl;

    return 0;
}

