#include <iostream>
#include <vector>
#include <string>

using namespace std;

int main() {
  int n, m;
  cin >> n >> m;

  vector<pair<int, char>> t(n);
  for (int i = 0; i < n; ++i) {
    int l;
    char c;
    cin >> l >> c;
    t[i] = {l, c};
  }

  vector<pair<int, char>> s(m);
  for (int i = 0; i < m; ++i) {
    int l;
    char c;
    cin >> l >> c;
    s[i] = {l, c};
  }

  string t_str = "";
  for (auto& p : t) {
    for (int i = 0; i < p.first; ++i) {
      t_str += p.second;
    }
  }

  string s_str = "";
  for (auto& p : s) {
    for (int i = 0; i < p.first; ++i) {
      s_str += p.second;
    }
  }

  int count = 0;
  for (int i = 0; i <= (int)t_str.length() - (int)s_str.length(); ++i) {
    if (t_str.substr(i, s_str.length()) == s_str) {
      count++;
    }
  }

  cout << count << endl;

  return 0;
}

