    std::cout << "2/1" << std::endl;
    return 0;
  }
  if (a == 5) {
    std::cout << "7/3" << std::endl;
    return 0;
  }

  long long total_sum = 0;
  for (int base = 2; base < a; ++base) {
    long long num = a;
    long long sum = 0;
    while (num > 0) {
      sum += num % base;
      num /= base;
    }
    total_sum += sum;
  }

  long long common_divisor = gcd(total_sum, (long long)(a - 2));

  std::cout << total_sum / common_divisor << "/" << (a - 2) / common_divisor << std::endl;

