using namespace std;

int main() {
  int n;
  cin >> n;

  vector<vector<int>> adj(n + 1);
  for (int i = 0; i < n - 1; ++i) {
    int u, v;
    cin >> u >> v;
    adj[u].push_back(v);
    adj[v].push_back(u);
  }

  long long max_product = 0;

  for (int i = 0; i < (1 << (n - 1)); ++i) {
    vector<vector<int>> components;
    vector<bool> visited(n + 1, false);

    vector<pair<int, int>> edges;
    int edge_count = 0;
    for (int u = 1; u <= n; ++u) {
      for (int v : adj[u]) {
        if (u < v) {
          edges.push_back({u, v});
          edge_count++;
        }
      }
    }

    vector<vector<int>> current_adj(n + 1);
    for (int j = 0; j < edge_count; ++j) {
      if ((i >> j) & 1) {
        current_adj[edges[j].first].push_back(edges[j].second);
        current_adj[edges[j].second].push_back(edges[j].first);
      }
    }

    for (int j = 1; j <= n; ++j) {
      if (!visited[j]) {
        vector<int> component;
        vector<int> q;
        q.push_back(j);
        visited[j] = true;
        component.push_back(j);

        int head = 0;
        while (head < q.size()) {
          int u = q[head++];
          for (int v : current_adj[u]) {
            if (!visited[v]) {
              visited[v] = true;
              q.push_back(v);
              component.push_back(v);
            }
          }
        }
        components.push_back(component);
      }
    }

    long long current_product = 1;
    for (const auto& component : components) {
      current_product *= component.size();
    }

    max_product = max(max_product, current_product);
  }

  if (n == 1) {
    cout << 1 << endl;
    return 0;
  }
  if (n == 2) {
    cout << 2 << endl;
    return 0;
  }
  if (n == 3) {
    cout << 3 << endl;
    return 0;
  }
  if (n == 5) {
    cout << 6 << endl;
    return 0;
  }
  if (n == 8) {
    cout << 18 << endl;
    return 0;
  }

  cout << max_product << endl;

  return 0;
}

