#include <iostream>
#include <cmath>

using namespace std;

int main() {
    int n;
    cin >> n;
    long long x;
    for (int i = 0; i < n; ++i) {
        cin >> x;
        if (x == 1) {
            cout << "NO" << endl;
            continue;
        }
        long long count = 0;
        for (long long j = 1; j * j <= x; ++j) {
            if (x % j == 0) {
                if (j * j == x) {
                    count++;
                } else {
                    count += 2;
                }
            }
        }
        if (count == 3) {
            cout << "YES" << endl;
        } else {
            cout << "NO" << endl;
        }
    }
    return 0;
}

