    cin >> dragons[i].first >> dragons[i].second;
  }

  sort(dragons.begin(), dragons.end());

  for (int i = 0; i < (1 << n); ++i) {
    int current_strength = s;
    bool possible = true;

    vector<int> order;
    for (int j = 0; j < n; ++j) {
      if ((i >> j) & 1) {
        order.push_back(j);
      }
    }

    for (int dragon_index : order) {
      if (current_strength <= dragons[dragon_index].first) {
        possible = false;
        break;
      }
      current_strength += dragons[dragon_index].second;
    }

    if (possible) {
      cout << "YES" << endl;
      return 0;
    }
  }

  cout << "NO" << endl;
  return 0;
}

