#include <iomanip>

using namespace std;

int main() {
  int n;
  cin >> n;

  vector<double> p(n);
  for (int i = 0; i < n; ++i) {
    cin >> p[i];
  }

  double expected_score = 0.0;
  for (int i = 0; i < (1 << n); ++i) {
    string play_sequence = "";
    double probability = 1.0;
    for (int j = 0; j < n; ++j) {
      if ((i >> j) & 1) {
        play_sequence += 'O';
        probability *= p[j];
      } else {
        play_sequence += 'X';
        probability *= (1.0 - p[j]);
      }
    }

    int score = 0;
    int current_o_count = 0;
    for (int j = 0; j < n; ++j) {
      if (play_sequence[j] == 'O') {
        current_o_count++;
      } else {
        if (current_o_count > 0) {
          score += current_o_count * current_o_count;
          current_o_count = 0;
        }
      }
    }
    if (current_o_count > 0) {
      score += current_o_count * current_o_count;
    }

    expected_score += probability * score;
  }

  cout << fixed << setprecision(10) << expected_score << endl;

  return 0;
}

