    string pre_ru = domain.substr(0, ru_pos);
    string post_ru = domain.substr(ru_pos + 2);

    if (post_ru.length() > 0) {
      cout << protocol << "://" << pre_ru << ".ru/" << post_ru << endl;
      return 0;
    } else {
      cout << protocol << "://" << pre_ru << ".ru" << endl;
      return 0;
