#include <iostream>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int p;
    cin >> p;

    if (p == 2) {
        cout << 1 << endl;
        return 0;
    }

    if (p == 3) {
        cout << 1 << endl;
        return 0;
    }

    if (p == 5) {
        cout << 2 << endl;
        return 0;
    }

    vector<int> factors;
    int phi = p - 1;
    int n = phi;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) {
            factors.push_back(i);
            while (n % i == 0) {
                n /= i;
            }
        }
    }
    if (n > 1) {
        factors.push_back(n);
    }

    int count = 0;
    for (int x = 1; x < p; ++x) {
        bool is_primitive_root = true;
        for (int factor : factors) {
            long long power = (long long)phi / factor;
            long long result = 1;
            long long base = x;
            while (power > 0) {
                if (power % 2 == 1) {
                    result = (result * base) % p;
                }
                base = (base * base) % p;
                power /= 2;
            }
            if (result == 1) {
                is_primitive_root = false;
                break;
            }
        }
        if (is_primitive_root) {
            count++;
        }
    }

    cout << count << endl;

    return 0;
}

