  if (x1 < x2) {
    for (int i = 0; i < dx; ++i) {
      path.push_back("R");
    }
  } else if (x1 > x2) {
    for (int i = 0; i < dx; ++i) {
      path.push_back("L");
    }
  }

  if (y1 < y2) {
    for (int i = 0; i < dy; ++i) {
      path.push_back("U");
    }
  } else if (y1 > y2) {
