      path.push_back("D");
    }
  }

  if (dx == 0 && dy == 0) {
      cout << 0 << endl;
      return 0;
  }

  if (dx == 1 && dy == 1) {
      cout << 1 << endl;
      cout << "RU" << endl;
      return 0;
