#include <algorithm>

using namespace std;

int main() {
  int n, v;
  cin >> n >> v;

  vector<pair<int, int>> vehicles(n);
  for (int i = 0; i < n; ++i) {
    cin >> vehicles[i].first >> vehicles[i].second;
  }

  long long max_capacity = 0;
  vector<int> best_set;

  for (int i = 0; i < (1 << n); ++i) {
    long long current_volume = 0;
    long long current_capacity = 0;
    vector<int> current_set;

    for (int j = 0; j < n; ++j) {
      if ((i >> j) & 1) {
        int type = vehicles[j].first;
        int capacity = vehicles[j].second;

        if (type == 1) {
          if (current_volume + 1 <= v) {
            current_volume += 1;
            current_capacity += capacity;
            current_set.push_back(j + 1);
          }
        } else {
          if (current_volume + 2 <= v) {
            current_volume += 2;
            current_capacity += capacity;
            current_set.push_back(j + 1);
          }
        }
      }
    }

    if (current_capacity > max_capacity) {
      max_capacity = current_capacity;
      best_set = current_set;
    }
  }

  cout << max_capacity << endl;
  for (int i = 0; i < best_set.size(); ++i) {
    cout << best_set[i] << (i == best_set.size() - 1 ? "" : " ");
  }
  cout << endl;

  return 0;
}

