#include <string>
#include <vector>
#include <algorithm>

using namespace std;

int main() {
    string pattern;
    cin >> pattern;

    int m = 0;
    for (char c : pattern) {
        if (c == '?') {
            m++;
        }
    }

    vector<pair<int, int>> costs(m);
    for (int i = 0; i < m; ++i) {
        cin >> costs[i].first >> costs[i].second;
    }

    long long min_cost = -1;
    string best_sequence = "";

    function<void(int, long long, string)> solve = 
        [&](int index, long long current_cost, string current_sequence) {
        if (index == pattern.length()) {
            int balance = 0;
            bool valid = true;
            for (char c : current_sequence) {
                if (c == '(') {
                    balance++;
                } else {
                    balance--;
                }
                if (balance < 0) {
                    valid = false;
                    break;
                }
            }
            if (balance != 0) {
                valid = false;
            }

            if (valid) {
                if (min_cost == -1 || current_cost < min_cost) {
                    min_cost = current_cost;
                    best_sequence = current_sequence;
                }
            }
            return;
        }

        if (pattern[index] == '?') {
            int cost_index = 0;
            int count = 0;
            for(int i = 0; i < pattern.length(); ++i){
                if(pattern[i] == '?'){
                    if(i == index){
                        cost_index = count;
                        break;
                    }
                    count++;
                }
            }

            // Replace with '('
            solve(index + 1, current_cost + costs[cost_index].first, current_sequence + '(');

            // Replace with ')'
            solve(index + 1, current_cost + costs[cost_index].second, current_sequence + ')');
        } else {
            solve(index + 1, current_cost, current_sequence + pattern[index]);
        }
    };

    solve(0, 0, "");

    if (min_cost == -1) {
        cout << -1 << endl;
    } else {
        cout << min_cost << endl;
        cout << best_sequence << endl;
    }

    return 0;
}

