#include <iostream>
#include <string>
#include <vector>

using namespace std;

int main() {
    string s;
    cin >> s;

    int n = s.length();
    vector<string> result;

    function<bool(int)> solve = [&](int start) {
        if (start == n) {
            return true;
        }

        for (int i = start; i < n; ++i) {
            string sub = s.substr(start, i - start + 1);
            size_t at_pos = sub.find('@');

            if (at_pos != string::npos && at_pos > 0 && at_pos < sub.length() - 1) {
                string a = sub.substr(0, at_pos);
                string b = sub.substr(at_pos + 1);

                bool valid_a = true;
                for (char c : a) {
                    if (!isalpha(c)) {
                        valid_a = false;
                        break;
                    }
                }

                bool valid_b = true;
                for (char c : b) {
                    if (!isalpha(c)) {
                        valid_b = false;
                        break;
                    }
                }

                if (valid_a && valid_b) {
                    result.push_back(sub);
                    if (solve(i + 1)) {
                        return true;
                    }
                    result.pop_back();
                }
            }
        }
        return false;
    };

    if (solve(0)) {
        for (size_t i = 0; i < result.size(); ++i) {
            cout << result[i];
            if (i < result.size() - 1) {
                cout << ",";
            }
        }
        cout << endl;
    } else {
        cout << "No solution" << endl;
    }

    return 0;
}

