using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        cin >> p[i];
    }

    vector<int> original(n);
    for (int i = 0; i < n; ++i) {
        original[i] = i + 1;
    }

    for (int l = 0; l < n - 1; ++l) {
        for (int r = l + 1; r < n; ++r) {
            vector<int> temp = original;
            reverse(temp.begin() + l, temp.begin() + r + 1);

            bool match = true;
            for (int i = 0; i < n; ++i) {
                if (temp[i] != p[i]) {
                    match = false;
                    break;
                }
            }

            if (match) {
                cout << l + 1 << " " << r + 1 << endl;
                return 0;
            }
        }
    }

    cout << 0 << " " << 0 << endl;

    return 0;
}

