#include <vector>
#include <algorithm>

using namespace std;

int main() {
    int n;
    cin >> n;

    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        cin >> p[i];
    }

    vector<int> original(n);
    for (int i = 0; i < n; ++i) {
        original[i] = i + 1;
    }

    bool found = false;
    int l = 0, r = 0;

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            vector<int> temp = original;
            reverse(temp.begin() + i, temp.begin() + j + 1);

            bool match = true;
            for (int k = 0; k < n; ++k) {
                if (temp[k] != p[k]) {
                    match = false;
                    break;
                }
            }

            if (match) {
                found = true;
                l = i + 1;
                r = j + 1;
                break;
            }
        }
        if (found) break;
    }

    if (found) {
        cout << l << " " << r << endl;
    } else {
        cout << 0 << " " << 0 << endl;
    }

    return 0;
}

