  for (int i = 0; i < (1 << n); ++i) {
    string bead = "";
    for (int j = 0; j < n; ++j) {
      if ((i >> j) & 1) {
        bead += '1';
      } else {
        bead += '0';
      }
    }
    beads.push_back(bead);
  }

  vector<string> unique_beads;
  for (const string& bead : beads) {
    bool found = false;
    for (const string& unique_bead : unique_beads) {
      string reversed_bead = unique_bead;
      reverse(reversed_bead.begin(), reversed_bead.end());

      string inverted_bead = unique_bead;
      for (char& c : inverted_bead) {
        c = (c == '0' ? '1' : '0');
      }

      string reversed_inverted_bead = inverted_bead;
      reverse(reversed_inverted_bead.begin(), reversed_inverted_bead.end());

      if (bead == unique_bead || bead == reversed_bead || bead == inverted_bead || bead == reversed_inverted_bead) {
        found = true;
        break;
      }
    }
    if (!found) {
      unique_beads.push_back(bead);
    }
  }

