#include <iostream>
#include <string>
#include <algorithm>

using namespace std;

long long reflection(long long n) {
    string s = to_string(n);
    string reflected_s = "";
    for (char c : s) {
        reflected_s += to_string(9 - (c - '0'));
    }

    // Remove leading zeros
    size_t first_digit = reflected_s.find_first_not_of('0');
    if (first_digit == string::npos) {
        return 0;
    }
    reflected_s = reflected_s.substr(first_digit);

    try {
        return stoll(reflected_s);
    } catch (const std::out_of_range& oor) {
        return 0;
    }
}

int main() {
    long long l, r;
    cin >> l >> r;

    long long max_weight = 0;
    for (long long i = l; i <= r; ++i) {
        long long ref = reflection(i);
        long long weight = i * ref;
        max_weight = max(max_weight, weight);
    }

    cout << max_weight << endl;

    return 0;
}

