    if (P > 0) {
      for (int k : data) {
        if (k <= 2 * P) {
          uniform_likelihood += log(1.0 / (2 * P));
        } else {
          uniform_likelihood = -1e18;
          break;
        }
      }
    } else {
      uniform_likelihood = -1e18;
